const items = $input.all();

const requiredFields = [
  "Product_ID",
  "Product_Name",
  "Category",
  "Current_Stock",
  "Minimum_Stock",
  "Maximum_Stock",
  "Unit_Price",
  "Supplier",
  "Last_Restock_Date"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {
  const data = item.json;

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  if (missingFields.length === 0) {
    validItems.push(data);
  } else {
    invalidItems.push({
      product_id: data.Product_ID || "Unknown",
      missing_fields: missingFields
    });
  }
}

return [
  {
    json: {
      data_valid: invalidItems.length === 0,
      total_products: items.length,
      valid_products: validItems.length,
      invalid_products: invalidItems.length,
      invalid_details: invalidItems,
      inventory_data: validItems
    }
  }
];

const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("AI returned invalid JSON: " + result);
}

return {
  json: {
    ...data,
    ...parsed
  }
};

const data = $json;

const products = data.products_requiring_attention || [];

return products.map(product => ({
  json: {
    alert_id: `INV-${Date.now()}-${product.product_id}`,

    report_date: new Date().toISOString().split("T")[0],

    product_id: product.product_id,
    product_name: product.product_name,

    current_stock: product.current_stock,

    stock_status: product.stock_status,
    alert_priority: product.alert_priority,

    recommended_action: product.recommended_action,
    reason: product.reason,

    overall_status: data.overall_status,

    recommendations: Array.isArray(data.recommendations)
      ? data.recommendations.join(" | ")
      : data.recommendations,

    created_at: new Date().toISOString()
  }
}));
